def seed_companies(db: Session):
    """Seed companies with official logos and deep interview intel."""
    seen_names = set()
    existing_names = {c.name for c in db.query(models.Company.name).all()}
    count = 0
    for c in COMPANIES:
        name = c["name"]
        if name in seen_names or name in existing_names:
            continue
        seen_names.add(name)

        company = models.Company(
            name=name,
            tier=c.get("tier", "Tier-2"),
            industry=c.get("industry", "Technology"),
            domain=c.get("domain"),
            logo_url=c.get("logo_url"),
            interview_focus=c.get("interview_focus", []),
            common_topics=c.get("common_topics", []),
            difficulty_level=c.get("difficulty_level", "Medium"),
            headquarters=c.get("headquarters"),
            description=c.get("description"),
            what_company_wants=c.get("what_company_wants"),
            interview_rounds=c.get("interview_rounds", []),
            prep_tips=c.get("prep_tips", [])
        )
        db.add(company)
        count += 1

    if count > 0:
        db.commit()
        logger.info("Seeded %d companies", count)
